using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A Bellman-Ford search in each language that works out the smaller of dist[u] + length and dist[v] and keeps it in the edge,
/// not as dist[v], so no shorter length is ever kept, with the change that keeps it as dist[v]; the same searches keeping it
/// there, and programs near the mistake but not it, which are left alone. Each row is what the check gave for the
/// program when these were written.
/// </summary>
public class PathLengthNotKeptTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

