    [Theory]
    [MemberData(nameof(Searches))]
    public void AShorterLengthKeptInTheEdgeIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The searches keeping each shorter length as the place's own; one doing it through a test; one in a map, through a name;
    /// a dynamic program rolling one row into the next; and the cheaper of two prices, kept as an answer of its own.
    /// </summary>
